import json
from pathlib import Path
root = Path('world/pages')
digest = '704c6ce7ad25ad66c08e1426c3cb5d43595df839866d978c6a7ec828396a1759'
def records(value, field):
    if isinstance(value, dict):
        if field in value:
            yield value
        else:
            for child in value.values():
                yield from records(child, field)
    elif isinstance(value, list):
        for child in value:
            yield from records(child, field)
review_files = sorted(root.glob('reviews-*.json'))
mission_files = sorted(root.glob('missions-*.json'))
reviews = [r for p in review_files for r in records(json.loads(p.read_text()), 'digest') if r.get('digest') == digest and r.get('subject') == 'site:sqlite-statement-diagnostic']
missions = [r for p in mission_files for r in records(json.loads(p.read_text()), 'mission_id') if r.get('mission_id') in {'SQLITE-CURATED-TOOLS-PLACEMENT', 'SQLITE-QUOTE-INTAKE-RELEASE-CANDIDATE'}]
print(json.dumps({'review_pages_read': len(review_files), 'mission_pages_read': len(mission_files), 'exact_digest_reviews': [{k:r.get(k) for k in ('verdict','host_provider','host_turn','seq')} for r in sorted(reviews,key=lambda r:r.get('seq',0))], 'missions': [{k:r.get(k) for k in ('mission_id','status','evidence')} for r in missions]}, indent=2))
